      "code": "E04B1/34A",
      "level": 1,
      "parent": "E04B1/34\\",
      "ja": "吊り構造〔例，サスペンシヨン技術，張弦梁，膜材を張設した屋根においてワイヤ－を吊りア－ムに挟着〕",
      "en": "Suspension structures, e.g. suspension techniques, suspended beams, gripped by arm after suspensing wires with filmed roof",
      "count": 256,
