      "level": 1,
      "parent": "E04B1/00\\",
      "ja": "可動，分離，または折りたたみができる部分に特徴がある構造，例．移動用（可動屋根Ｅ０４Ｂ７／１６；水上浮揚構造物Ｂ６３Ｂ；全体として移動可能な小形プレハブ建築物Ｅ０４Ｈ１／１２；小ガレージＥ０４Ｈ６／０２；テントまたは天蓋一般Ｅ０４Ｈ１５／００）",
      "en": "Structures characterised by movable, separable, or collapsible parts, e.g. for transport (movable roof parts E04B 7/16; floatable buildings B63B; small prefabricated buildings, transportable as a whole, E04H 1/12; small garages E04H 6/02; tents or canopies, in general E04H 15/00)",
