      "level": 1,
      "parent": "E04B1/00\\",
      "ja": "絶縁または他の保護；要素またはそのための特殊な材料の使用（化学的組成物Ｃ０１～Ｃ１１；絶縁またはシーリングに適用する器具Ｅ０４Ｆ２１／００；望ましくない外部の影響に対する耐性を持つか保護を提供する建築物Ｅ０４Ｈ９／００；壁または間仕切り中の管の密封Ｆ１６Ｌ５／０２；有害な放射線に対する遮蔽Ｇ２１Ｆ；建築物の特殊部分の構造は，それらの関連グループ参照）［２００６．０１］",
      "en": "Insulation or other protection; Elements or use of specified material therefor (chemical compositions C01-C11;implements for applying insulation or sealings E04F0021000000;buildings to withstand, or to provide protection against, external undesired influences E04H0009000000;sealing pipes in walls or partitions F16L0005020000;shielding against dangerous radiation G21F)[2006.01]",
